insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000415491', '40000000-0000-4000-8000-000000041549', 'Substitua as coordenadas paramétricas da reta no plano.', 1), ('60000000-0000-4000-8000-000000415492', '40000000-0000-4000-8000-000000041549', 'A soma das três coordenadas será n mais 3t.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000041549', '$t=10$.', 'Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000415491', '40000000-0000-4000-8000-000000041549', 'Escreva as coordenadas', '$x=t, y=9+t, z=t.$', 1), ('70000000-0000-4000-8000-000000415492', '40000000-0000-4000-8000-000000041549', 'Substitua no plano', '$t+(9+t)+t=39.$', 2), ('70000000-0000-4000-8000-000000415493', '40000000-0000-4000-8000-000000041549', 'Resolva', '$3t=30 \Rightarrow t=10.$', 3)
